// Browserless /function returns Puppeteer result directly as JSON.
// fusionAuthUrl + drupalCookies already extracted by headless Chrome — no header parsing needed.
const raw = $input.first().json;
const resp = raw.data || raw;
const fusionAuthUrl = resp.fusionAuthUrl || '';
const drupalCookieStr = resp.drupalCookies || '';
const drupalSessionCookie = resp.drupalSessionCookie || '';

if (!fusionAuthUrl) {
  throw new Error('Browserless: No FusionAuth URL captured. currentUrl=' + (resp.currentUrl || 'unknown'));
}

return [{json: {
  fusionAuthUrl,
  drupalCookies: drupalCookieStr,
  drupalSessionCookie,
  faCookies: resp.faCookies || '',
  fusionAuthHtml: resp.fusionAuthHtml || '',
  statusCode: 302
}}];

