// Post Login Form is now a browserless call that returns sessionCookie directly
const raw = $input.first().json;
const resp = raw.data || raw;
const sessionCookie = resp.sessionCookie || '';
const cookieStr = resp.cookieStr || '';
const finalUrl = resp.finalUrl || '';

if (!sessionCookie) {
  throw new Error('Browserless login: no SSESS cookie returned. finalUrl=' + finalUrl + ' cookies=' + cookieStr);
}

return [{ json: { sessionCookie, cookieStr, finalUrl } }];

const resp = $input.first().json;
const headers = resp.headers || {};
const location = headers.location || '';
const prevCookies = $('Extract Redirect URL').first().json.cookies || '';
const setCookies = headers['set-cookie'] || [];
const cookieArr = Array.isArray(setCookies) ? setCookies : [setCookies];
const parsed = {};
for (const pair of prevCookies.split('; ')) {
  const [k,...v] = pair.split('=');
  if (k) parsed[k] = v.join('=');
}
for (const c of cookieArr) {
  if (typeof c === 'string') {
    const parts = c.split(';')[0].split('=');
    parsed[parts[0]] = parts.slice(1).join('=');
  }
}
const mergedCookies = Object.entries(parsed).map(([k,v]) => k+'='+v).join('; ');
let consentUrl = location;
if (consentUrl.startsWith('/')) consentUrl = 'https://accounts.scrum.org' + consentUrl;
return [{json:{consentUrl, cookies: mergedCookies, status: resp.statusCode}}];

// OAuth callback returns meta-refresh to /user/login?destination=...
// Extract destination and carry Drupal cookies for the callback
const resp = $input.first().json;
const body = resp.body || resp.data || '';
const headers = resp.headers || {};

// Get Drupal cookies from initial login page
const drupalCookies = $('Build Login Body').first().json.drupalCookies || '';

// Merge all cookies
const prevCookies = $('Build Callback URL').first().json.cookies || '';
const setCookies = headers['set-cookie'] || [];
const cookieArr = Array.isArray(setCookies) ? setCookies : [setCookies];
const parsed = {};
for (const pair of prevCookies.split('; ')) {
  const [k,...v] = pair.split('='); if (k) parsed[k] = v.join('=');
}
for (const c of cookieArr) {
  if (typeof c === 'string') { const p = c.split(';')[0].split('='); parsed[p[0]] = p.slice(1).join('='); }
}
for (const pair of drupalCookies.split('; ')) {
  const [k,...v] = pair.split('='); if (k) parsed[k] = v.join('=');
}
const mergedCookies = Object.entries(parsed).map(([k,v]) => k + '=' + v).join('; ');

// Parse meta-refresh URL
const metaMatch = body.match(/url='([^']+)'/) || body.match(/url=([^\"'\s>]+)/i);
if (!metaMatch) throw new Error('No meta-refresh URL found. Status=' + resp.statusCode);
let fullUrl = metaMatch[1].replace(/&amp;/g, '&');
if (fullUrl.startsWith('/')) fullUrl = 'https://www.scrum.org' + fullUrl;

// Extract destination param using regex (more reliable than URL parser in n8n)
let callbackUrl = fullUrl;
const destMatch = fullUrl.match(/[?&]destination=([^&]+)/);
if (destMatch) {
  const destination = decodeURIComponent(destMatch[1]);
  callbackUrl = 'https://www.scrum.org/' + destination.replace(/^\//, '');
}

return [{json: {callbackUrl, cookies: mergedCookies, drupalCookies, originalUrl: fullUrl, destFound: !!destMatch}}];

const html = $input.first().json.data || '';
const courses = [];

const rows = html.split('<tr>');
for (let i = 1; i < rows.length; i++) {
  const row = rows[i];

  const scoreMatch = row.match(/score-report\?courseId=([a-f0-9\-]+)/);
  if (!scoreMatch) continue;
  const courseId = scoreMatch[1];

  const titleMatch = row.match(/views-field-title[\s\S]*?<a[^>]*>([^<]+)<\/a>/);
  const title = titleMatch ? titleMatch[1].trim() : 'Unknown';

  // Student count: look for the actual number after the emoji entity
  // HTML: <span class="student-count-tag">&#128100; 15</span>
  const studentTagMatch = row.match(/student-count-tag[^>]*>&#\d+;\s*(\d+)/);
  const studentCount = studentTagMatch ? parseInt(studentTagMatch[1]) : 0;

  const dateMatch = row.match(/views-field-course-date-range[^>]*>\s*([^<]+)</);
  const date = dateMatch ? dateMatch[1].trim() : '';

  const statusMatch = row.match(/views-field-course-status-combined[^>]*>\s*([^<]+)</);
  const status = statusMatch ? statusMatch[1].trim() : '';

  courses.push({ json: { courseId, title, date, studentCount, status, _hasReport: true } });
}

if (courses.length === 0) {
  return [{ json: { _empty: true, message: 'No courses with score reports found in last 30 days' } }];
}
return courses;

const courses = $('Parse Course List').all().map(i => i.json);
const allRows = $input.all().map(i => i.json);

// Split the flat row stream into per-course groups.
// Each Excel file starts with a row where Details='Type'.
const groups = [];
let current = [];
for (const row of allRows) {
  if (row.Details === 'Type' && current.length > 0) {
    groups.push(current);
    current = [];
  }
  current.push(row);
}
if (current.length > 0) groups.push(current);

const results = [];
for (let i = 0; i < groups.length; i++) {
  const rows = groups[i];
  const course = courses[i] || {};

  // Assessment info: row with Details='Date' has assessment name, passing %, avg score
  let assessmentName = '';
  let passingPct = null;
  let avgScore = null;
  for (const row of rows) {
    if (row.Details === 'Date' && row['Assessment Data']) {
      assessmentName = row['Assessment Data'];
      passingPct = typeof row.__EMPTY_2 === 'number' ? Math.round(row.__EMPTY_2) : null;
      avgScore = typeof row.__EMPTY_3 === 'number' ? Math.round(row.__EMPTY_3 * 10) / 10 : null;
      break;
    }
  }

  // Students: find header row (Details='First Name'), then extract rows after it
  const students = [];
  let inStudents = false;
  for (const row of rows) {
    if (row.Details === 'First Name') {
      inStudents = true;
      continue;
    }
    if (inStudents) {
      if (!row.Details) break;
      students.push({
        firstName: row.Details || '',
        lastName: row.__EMPTY || '',
        completedAssessment: row.__EMPTY_4 === true,
        attempts: parseInt(row.__EMPTY_5) || 0,
        score: typeof row.__EMPTY_6 === 'number' ? Math.round(row.__EMPTY_6 * 10) / 10 : null,
        passed: row.__EMPTY_8 === true
      });
    }
  }

  results.push({
    json: {
      courseId: course.courseId || '',
      courseTitle: course.title || '',
      courseDate: course.date || '',
      assessmentName,
      passingPct,
      avgScore,
      students
    }
  });
}

return results;

const items = $input.all();
const lines = [];
lines.push(`\ud83d\udcca *Score Reports \u2014 Last 30 days* (${items.length} course${items.length !== 1 ? 's' : ''})`);
lines.push('');
for (const item of items) {
  const d = item.json;
  const students = d.students || [];
  const passed = students.filter(s => s.passed).length;
  const failed = students.filter(s => s.completedAssessment && !s.passed).length;
  const notTaken = students.filter(s => !s.completedAssessment).length;
  lines.push(`*${d.courseTitle} \u2014 ${d.courseDate}*`);
  if (d.assessmentName) {
    const pct = d.passingPct != null ? ` | Threshold: ${d.passingPct}%` : '';
    const avg = d.avgScore != null ? ` | Avg: ${d.avgScore}%` : '';
    lines.push(`_${d.assessmentName}${pct}${avg}_`);
  }
  lines.push('');
  for (const s of students) {
    const name = (`${s.firstName} ${s.lastName}`).substring(0, 28).padEnd(28);
    if (!s.completedAssessment) {
      lines.push(`\u2022 ${name}  \u23f3 not taken`);
    } else {
      const result = s.passed ? '\u2705 PASS' : '\u274c FAIL';
      const scoreStr = s.score != null ? `${s.score}%`.padStart(5) : '  N/A';
      const attStr = s.attempts > 1 ? `(${s.attempts}x)` : '    ';
      lines.push(`\u2022 ${name}  ${scoreStr}  ${attStr}  ${result}`);
    }
  }
  if (students.length > 0) {
    lines.push('');
    lines.push(`_\u2705 ${passed} passed | \u274c ${failed} failed${notTaken > 0 ? ` | \u23f3 ${notTaken} not taken` : ''}_`);
  } else {
    lines.push('_No student data_');
  }
  lines.push('\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500');
  lines.push('');
}
return [{ json: { text: lines.join('\n') } }];

// Extract OAuth callback URL from consent page 302 and merge cookies
const resp = $input.first().json;
const headers = resp.headers || {};
const location = headers.location || '';

const prevCookies = $('Build Consent URL').first().json.cookies || '';
const setCookies = headers['set-cookie'] || [];
const cookieArr = Array.isArray(setCookies) ? setCookies : [setCookies];
const parsed = {};
for (const pair of prevCookies.split('; ')) {
  const [k,...v] = pair.split('='); if (k) parsed[k] = v.join('=');
}
for (const c of cookieArr) {
  if (typeof c === 'string') { const p = c.split(';')[0].split('='); parsed[p[0]] = p.slice(1).join('='); }
}
const mergedCookies = Object.entries(parsed).map(([k,v])=>k+'='+v).join('; ');

if (!location) throw new Error('No redirect from consent page, status=' + resp.statusCode);

// Merge www.scrum.org drupal/WAF cookies so the callback to www.scrum.org passes WAF
const drupalCookies = $('Build Login Body').first().json.drupalCookies || '';
for (const pair of drupalCookies.split('; ')) {
  const [k,...v] = pair.split('='); if (k) parsed[k] = v.join('=');
}
const finalCookies = Object.entries(parsed).map(([k,v])=>k+'='+v).join('; ');

return [{json:{callbackUrl: location, cookies: finalCookies}}];

// Session cookie comes directly from Extract Redirect URL (browserless completed full login)
const d = $input.first().json;
const sessionCookie = d.sessionCookie || '';
if (!sessionCookie) {
  throw new Error('No SSESS cookie. Cookies: ' + (d.cookieStr || ''));
}
const cookieStr = d.cookieStr || sessionCookie;
return [{ json: { sessionCookie, cookieStr } }];

const MONTH_MAP = {
  'Jan': 'stycznia', 'Feb': 'lutego', 'Mar': 'marca', 'Apr': 'kwietnia',
  'May': 'maja', 'Jun': 'czerwca', 'Jul': 'lipca', 'Aug': 'sierpnia',
  'Sep': 'wrze\u015bnia', 'Oct': 'pa\u017adziernika', 'Nov': 'listopada', 'Dec': 'grudnia'
};

const COURSE_MAP = {
  'Applying Professional Scrum': { abbr: 'APS', id: '1h8PGDdsTbtJaYZLfx1RkYeprU54aA5epJ_v8IFJv7tA' },
  'Professional Scrum Master - Advanced': { abbr: 'PSM-A', id: '1uSeglZgAnO_AKNyQX2QPqPl-CTlHzUEA-GpmlMV4Q0U' },
  'Professional Scrum Master': { abbr: 'PSM', id: '1vlMyKfvHr7hkHAjTZAChvbcmsoOAsSvlC_KjGbE55a4' },
  'Professional Scrum Product Owner - Advanced': { abbr: 'A-PSPO', id: '1ZhzKqyw0jaCWzrW65UM-qqElbydztawUvD-BqtMa25o' },
  'Professional Scrum Product Owner - AI Essentials': { abbr: 'PSPO-AI', id: '1JSEW5y1_SV1ttYAa6hdTALfwoehWCGXFU1CbygrQ3sk' },
  'Professional Scrum Product Owner': { abbr: 'PSPO', id: '1zrAgYWG2yLhtb8pjHIwWOckD4kJGiKcAY1-ckwhfK0s' },
  'Professional Agile Leadership - Evidence-Based Management': { abbr: 'PAL-EBM', id: '1h4SsPZXaxOvhVKIF6sQ-fnhlj3bxhGvsmOsMemVU1ns' },
  'Professional Agile Leadership - Essentials': { abbr: 'PAL-E', id: '1JqSy-I75r4T3nNHX8VBoAT56J74DzUqzp9OZbM3yoxo' },
  'Scaled Professional Scrum': { abbr: 'SPS', id: '1Yr0ExrBOTjEztR9KJUuXlzghUE1sYb7-mfTFEzfi73k' },
  'Professional Scrum with Kanban': { abbr: 'PSK', id: '1sRb-us30F8YJlF6WAzAEH07cNRTQHzPf8vW3TW1dzF8' },
  'Team Kanban Practitioner': { abbr: 'TKP', id: '1oVM-h2IW0WgOv2MGr_D-G5Aokq0s6_oZAMMpGXsRCQ8' },
  'Professional Scrum Facilitation Skills': { abbr: 'PSFS', id: '1Ho3uquyra5tXokyarsovBDlaIMUYNSdjoDU61l3dU-Q' }
};

const PRIVATE_SHEET_ID = '1U_m-bpEmK5UbNNmzsYXwmJpDYVueCxp8z1sukNpPTMA';

function parseDateToTabName(dateStr) {
  const m = dateStr.match(/(\w+)\s+(\d+(?:-\d+)?),?\s*\d{4}/);
  if (!m) return null;
  const monthPl = MONTH_MAP[m[1]];
  if (!monthPl) return null;
  return m[2] + ' ' + monthPl;
}

// Sort by key length descending so more specific names match before shorter ones
// e.g. 'Professional Scrum Product Owner - Advanced' before 'Professional Scrum Product Owner'
const sortedEntries = Object.entries(COURSE_MAP).sort((a, b) => b[0].length - a[0].length);

function findCourseMapping(title) {
  for (const [name, info] of sortedEntries) {
    if (title.includes(name)) return { ...info, matchedKey: name };
  }
  return null;
}

const results = [];
for (const item of $input.all()) {
  const d = item.json;
  const mapping = findCourseMapping(d.courseTitle);
  const tabName = parseDateToTabName(d.courseDate);

  let spreadsheetId, sheetTab, isPrivateCourse;
  if (mapping) {
    spreadsheetId = mapping.id;
    sheetTab = tabName;
    isPrivateCourse = false;
  } else {
    spreadsheetId = PRIVATE_SHEET_ID;
    sheetTab = null;
    isPrivateCourse = true;
  }

  results.push({ json: {
    ...d,
    spreadsheetId,
    sheetTab,
    isPrivateCourse,
    courseAbbr: mapping ? mapping.abbr : 'PRIVATE',
    tabSearchHint: tabName
  }});
}

return results;

// Native googleSheets Read node returns rows as objects with header keys + row_number.
const course = $('Loop Courses').first().json;
const sheetRows = $input.all().map(i => i.json);

if (sheetRows.length === 0) {
  return [{ json: { skip: true, reason: 'Empty sheet', courseTitle: course.courseTitle, spreadsheetId: course.spreadsheetId, sheetTab: course.sheetTab } }];
}

const sampleRow = sheetRows[0];
const keys = Object.keys(sampleRow).filter(k => k !== 'row_number');

const firstNameKey = keys.find(k => k.toLowerCase().includes('imi') && !k.toLowerCase().includes('nazwisko') && !k.toLowerCase().includes('i nazwisko')) || keys[0];
const lastNameKey = keys.find(k => k.toLowerCase().includes('nazwisko') && !k.toLowerCase().includes('i nazwisko')) || keys[1];
const emailKey = keys.find(k => k.toLowerCase().includes('email'));

// Determine assessment column index (0-based)
// If 'Egzamin' header already exists, use its position; otherwise append after last column
const hasEgzamin = keys.includes('Egzamin');
let assessCol;
if (hasEgzamin) {
  assessCol = keys.indexOf('Egzamin');
} else {
  assessCol = keys.length; // append after last header
}

const students = course.students || [];
const results = [];
const unmatched = [];

for (const student of students) {
  const fn = (student.firstName || '').trim().toLowerCase();
  const ln = (student.lastName || '').trim().toLowerCase();

  let matchedRow = null;
  for (const row of sheetRows) {
    const cellFn = (row[firstNameKey] || '').trim().toLowerCase();
    const cellLn = (row[lastNameKey] || '').trim().toLowerCase();
    if (cellFn === fn && cellLn === ln) { matchedRow = row; break; }
  }

  if (!matchedRow && emailKey) {
    const email = (student.email || '').trim().toLowerCase();
    if (email) matchedRow = sheetRows.find(r => (r[emailKey] || '').trim().toLowerCase() === email) || null;
  }

  if (!matchedRow) { unmatched.push(student.firstName + ' ' + student.lastName); continue; }

  // Skip if already filled
  if (hasEgzamin && matchedRow['Egzamin'] && matchedRow['Egzamin'].toString().trim() !== '') continue;

  const scoreStr = student.score != null ? student.score + '%' : '\u2014';
  const passedStr = student.completedAssessment ? (student.passed ? 'TAK' : 'NIE') : '\u2014';
  const attemptsStr = student.attempts > 0 ? String(student.attempts) : '\u2014';

  results.push({ json: {
    spreadsheetId: course.spreadsheetId,
    sheetTab: course.sheetTab,
    row_number: matchedRow.row_number,
    assessCol,
    needsHeader: !hasEgzamin,
    'Egzamin': course.assessmentName || '\u2014',
    'Wynik': scoreStr,
    'Pr\u00f3by': attemptsStr,
    'Zda\u0142/a': passedStr
  }});
}

if (unmatched.length > 0) console.log('Unmatched:', unmatched.join(', '));

if (results.length === 0) {
  return [{ json: { skip: true, reason: 'No students to update', courseTitle: course.courseTitle, spreadsheetId: course.spreadsheetId, sheetTab: course.sheetTab } }];
}

return results;

const course = $('Loop Courses').first().json;
const item = $input.first().json;
const msg = item.error?.message || item.message || item.description || JSON.stringify(item);
console.warn(`[${course.courseAbbr}] Sheet tab "${course.sheetTab}" not found — skipping. Error: ${msg}`);
// Return skip item so the loop continues gracefully
return [{ json: { skip: true, reason: `Tab "${course.sheetTab}" not found in ${course.courseAbbr} spreadsheet`, courseTitle: course.courseTitle, spreadsheetId: course.spreadsheetId, sheetTab: course.sheetTab } }];

const items = $input.all();
if (items.length === 0) return [];

const first = items[0].json;
const spreadsheetId = first.spreadsheetId;
const sheetTab = first.sheetTab;
const assessCol = first.assessCol;

function colLetter(idx) {
  let s = '', n = idx;
  while (n >= 0) { s = String.fromCharCode(65 + (n % 26)) + s; n = Math.floor(n / 26) - 1; }
  return s;
}

const data = [];

// Add header row if this is a new assessment column (assessCol points beyond existing headers)
// We detect this by checking if any item has a row_number — if assessCol >= keys in sheet,
// we need headers. Pass a flag from Match Students to know.
// Simple heuristic: if assessCol is not -1 and first item signals needsHeader
if (first.needsHeader) {
